<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { useRoute } from 'vue-router'; import { createApiClient } from '../api/client'; import { createIdempotencyKey } from '../api/idempotency'; import type { ChatMessage } from '../api/contracts';
const route=useRoute(); const client=createApiClient(); const messages=ref<ChatMessage[]>([]); const text=ref(''); const loading=ref(true); const quick=['我已确认费用分摊','预计准时到达','请发一下上车点'];
async function load(){ messages.value=await client.listMessages(String(route.params.id)); loading.value=false }; async function send(){if(!text.value.trim())return; messages.value.push(await client.sendMessage(String(route.params.id),text.value,createIdempotencyKey())); text.value=''}; onMounted(load)
</script>
<template><main class="page"><div class="eyebrow">同行沟通</div><h1>聊天</h1><div v-if="loading" class="async-state">正在加载消息…</div><div v-else class="chat-list"><article v-for="m in messages" :key="m.id" class="detail-card"><p>{{ m.text }}</p><small class="muted">{{ new Date(m.createdAt).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}) }}</small></article></div><div class="choice-row"><button v-for="q in quick" :key="q" class="secondary-button" @click="text=q">{{ q }}</button></div><form class="chat-input" @submit.prevent="send"><input v-model="text" aria-label="消息" placeholder="输入消息"/><button class="primary-button">发送</button></form><a class="text-button" href="tel:110">紧急情况拨打 110</a></main></template>
